static bool dfs(int **adj, int *adjSize, int node, int target, bool *visited) {
  if (node == target) return true;
  if (visited[node]) return false;
  visited[node] = true;
  for (int i = 0; i < adjSize[node]; i++) {
    if (dfs(adj, adjSize, adj[node][i], target, visited)) return true;
  }
  return false;
}

bool findWhetherExistsPath(int n, int **graph, int graphSize, int *graphColSize, int start, int target) {
  (void)graphColSize;
  int N = n + 1;
  int **adj = (int **)malloc(sizeof(int *) * N);
  int *adjSize = (int *)calloc(N, sizeof(int));
  int *cap = (int *)malloc(sizeof(int) * N);
  for (int i = 0; i < N; i++) {
    cap[i] = 4;
    adj[i] = (int *)malloc(sizeof(int) * 4);
  }
  for (int i = 0; i < graphSize; i++) {
    int u = graph[i][0], v = graph[i][1];
    if (adjSize[u] == cap[u]) {
      cap[u] *= 2;
      adj[u] = (int *)realloc(adj[u], sizeof(int) * cap[u]);
    }
    adj[u][adjSize[u]++] = v;
  }
  bool *visited = (bool *)calloc(N, sizeof(bool));
  bool res = dfs(adj, adjSize, start, target, visited);
  for (int i = 0; i < N; i++) free(adj[i]);
  free(adj);
  free(adjSize);
  free(cap);
  free(visited);
  return res;
}

class Solution {
  bool dfs(vector<vector<int>> &adj, int node, int target, vector<bool> &visited) {
    if (node == target) return true;
    if (visited[node]) return false;
    visited[node] = true;
    for (int next : adj[node]) {
      if (dfs(adj, next, target, visited)) return true;
    }
    return false;
  }

public:
  bool findWhetherExistsPath(int n, vector<vector<int>> &graph, int start, int target) {
    vector<vector<int>> adj(n + 1);
    for (auto &edge : graph) adj[edge[0]].push_back(edge[1]);
    vector<bool> visited(n + 1, false);
    return dfs(adj, start, target, visited);
  }
};

func findWhetherExistsPath(n int, graph [][]int, start int, target int) bool {
	adj := make([][]int, n+1)
	for _, e := range graph {
		adj[e[0]] = append(adj[e[0]], e[1])
	}
	visited := make([]bool, n+1)
	var dfs func(node int) bool
	dfs = func(node int) bool {
		if node == target {
			return true
		}
		if visited[node] {
			return false
		}
		visited[node] = true
		for _, next := range adj[node] {
			if dfs(next) {
				return true
			}
		}
		return false
	}
	return dfs(start)
}

class Solution {
  private boolean dfs(List<List<Integer>> adj, int node, int target, boolean[] visited) {
    if (node == target) return true;
    if (visited[node]) return false;
    visited[node] = true;
    for (int next : adj.get(node)) {
      if (dfs(adj, next, target, visited)) return true;
    }
    return false;
  }

  public boolean findWhetherExistsPath(int n, int[][] graph, int start, int target) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : graph) adj.get(e[0]).add(e[1]);
    return dfs(adj, start, target, new boolean[n + 1]);
  }
}

class Solution:
    def findWhetherExistsPath(self, n: int, graph: List[List[int]], start: int, target: int) -> bool:
        adj = [[] for _ in range(n + 1)]
        for u, v in graph:
            adj[u].append(v)
        visited = [False] * (n + 1)

        def dfs(node: int) -> bool:
            if node == target:
                return True
            if visited[node]:
                return False
            visited[node] = True
            return any(dfs(nxt) for nxt in adj[node])

        return dfs(start)

impl Solution {
  pub fn find_whether_exists_path(n: i32, graph: Vec<Vec<i32>>, start: i32, target: i32) -> bool {
    let n = n as usize;
    let mut adj: Vec<Vec<i32>> = vec![vec![]; n + 1];
    for e in &graph {
      adj[e[0] as usize].push(e[1]);
    }
    let mut visited = vec![false; n + 1];
    fn dfs(adj: &Vec<Vec<i32>>, node: i32, target: i32, visited: &mut Vec<bool>) -> bool {
      if node == target {
        return true;
      }
      if visited[node as usize] {
        return false;
      }
      visited[node as usize] = true;
      for &next in &adj[node as usize] {
        if dfs(adj, next, target, visited) {
          return true;
        }
      }
      false
    }
    dfs(&adj, start, target, &mut visited)
  }
}

const findWhetherExistsPath = (n: number, graph: number[][], start: number, target: number): boolean => {
  const adj: number[][] = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of graph) adj[u].push(v);
  const visited: boolean[] = new Array(n + 1).fill(false);
  const dfs = (node: number): boolean => {
    if (node === target) return true;
    if (visited[node]) return false;
    visited[node] = true;
    return adj[node].some((next) => dfs(next));
  };
  return dfs(start);
};
